var e=[{id:`split-ac`,name:`Split AC`,group:`Residential`,blurb:`Air handler inside, condenser outside.`},{id:`heat-pump`,name:`Heat pump`,group:`Residential`,blurb:`Cools and heats with a reversing valve.`},{id:`gas-furnace`,name:`Gas furnace`,group:`Residential`,blurb:`Burners, inducer, and heat exchanger.`},{id:`mini-split`,name:`Mini-split`,group:`Residential`,blurb:`Ductless head and outdoor unit.`},{id:`package`,name:`Package unit`,group:`Residential`,blurb:`All-in-one pad or roof unit.`},{id:`rtu`,name:`Rooftop unit`,group:`Commercial`,blurb:`Packaged RTU with economizer and stages.`},{id:`commercial-ahu`,name:`Commercial AHU`,group:`Commercial`,blurb:`Air handler, VAV, coils, big fans.`},{id:`chiller`,name:`Chiller plant`,group:`Commercial`,blurb:`Air- or water-cooled chilled water.`},{id:`walk-in`,name:`Walk-in box`,group:`Commercial`,blurb:`Cooler or freezer with a condensing unit.`},{id:`boiler`,name:`Boiler / hydronic`,group:`Commercial`,blurb:`Hot water or steam heat.`}],t=[{id:`no-cool`,name:`No cooling`},{id:`no-heat`,name:`No heat`},{id:`no-start`,name:`Won't start`},{id:`ice`,name:`Ice on lines or coil`},{id:`water`,name:`Water leak`},{id:`short-cycle`,name:`Short cycling`},{id:`noise`,name:`Noise or vibration`},{id:`high-bill`,name:`High bill / weak airflow`},{id:`odor`,name:`Smell or fumes`},{id:`uneven`,name:`Hot and cold rooms`}];function n(t){return e.find(e=>e.id===t)}function r(e){return t.find(t=>t.id===e)}var i=[{id:`split-ac`,title:`Residential split air conditioner`,summary:`Indoor coil and blower, outdoor compressor and fan, copper lineset between them.`,safety:[`Power can stay live at the disconnect even when the thermostat is off.`,`Capacitors hold a charge after power is removed. Do not poke inside the outdoor unit.`,`Refrigerant work requires EPA 608. Adding gas by guesswork ruins compressors.`],steps:[{title:`Confirm the call`,who:`anyone`,body:`Set the thermostat to Cool, a few degrees below room temperature, fan Auto. Wait 5 minutes. Note whether the indoor blower and the outdoor unit both run.`},{title:`Air path first`,who:`anyone`,body:`Check the filter, supply and return grilles, and the indoor drain pan. A dirty filter or blocked return is the most common “no cool.”`},{title:`Look at the outdoor unit`,who:`anyone`,body:`Is the fan spinning? Is the disconnect on? Is the breaker on? Is the coil packed with cottonwood or grass? Listen for a hum with no start — that is a tech job (capacitor / start components).`},{title:`Ice check`,who:`anyone`,body:`If the suction line or indoor coil is iced, turn the system to Off and the fan to On. Let it thaw. Do not chip ice. After thaw, restart and watch whether ice returns.`},{title:`Condensate`,who:`helper`,body:`A full drain pan or tripped float switch kills cooling on many air handlers. Clear the trap and the PVC if you can see the stand.`},{title:`Electrical and charge`,who:`tech`,body:`Measure incoming voltage, capacitor MFD, amp draw vs nameplate, superheat and subcooling. Weigh in only to the data plate plus lineset add-on.`}]},{id:`heat-pump`,title:`Heat pump`,summary:`Same hardware as a split AC plus a reversing valve. Aux / emergency heat is electric strips or a furnace.`,safety:[`Emergency heat is expensive. Use it for backup, not everyday running, unless the outdoor unit is down.`,`Do not force heat mode with an iced outdoor coil without defrost diagnosis.`],steps:[{title:`Mode and setpoint`,who:`anyone`,body:`Heat mode, setpoint a few degrees above room temp. Confirm the thermostat is not stuck in Emergency Heat unless you chose that.`},{title:`Which unit is running`,who:`anyone`,body:`In mild weather the outdoor unit should run. Very cold weather may bring on aux heat. If the outdoor fan and compressor are off in 50°F weather, start there.`},{title:`Defrost clues`,who:`helper`,body:`Outdoor frost in heat mode can be normal. A solid block of ice, steam for a long time, or loud hissing every few minutes needs a defrost check (sensors, board, reversing valve).`},{title:`Airflow`,who:`anyone`,body:`Same filter and grille checks as cooling. Low airflow in heat causes high head and strip-heat lockouts.`},{title:`Reversing valve and charge`,who:`tech`,body:`Confirm valve shift, check charge in the mode the IOM specifies, and test defrost termination. Do not swap a valve until the coil and sensors check out.`}]},{id:`gas-furnace`,title:`Gas furnace`,summary:`Inducer, igniter or pilot, gas valve, burners, heat exchanger, blower.`,safety:[`If you smell gas, leave the building, do not flip switches, and call the gas utility or fire department.`,`Cracked heat exchangers can leak carbon monoxide. CO alarms are not optional.`,`Do not bypass limit or rollout switches.`],steps:[{title:`Thermostat call`,who:`anyone`,body:`Heat mode, setpoint above room temp. Furnaces often wait 30–90 seconds before the blower starts. Listen for the small inducer motor first.`},{title:`Air and filter`,who:`anyone`,body:`A plugged filter overheats the furnace and trips the limit. Replace it and reset power once if the unit locked out.`},{title:`Status lights`,who:`helper`,body:`Open the blower door carefully. Many boards blink a code. Count the flashes and write them down before you cycle power.`},{title:`Ignition sequence`,who:`helper`,body:`Inducer → pressure switch → igniter glow → gas valve click → flame. If it tries three times and locks out, do not keep resetting. That is a tech visit.`},{title:`Combustion and exchanger`,who:`tech`,body:`Manometer on the gas valve, flame-sense microamps, flue draft, heat-exchanger inspection, CO in the supply. Never seal a cracked exchanger.`}]},{id:`mini-split`,title:`Ductless mini-split`,summary:`Wall or cassette head, outdoor inverter compressor, small lineset, onboard leak sensors on A2L units.`,safety:[`Inverter boards store high voltage. Wait after disconnect before opening the outdoor cabinet.`,`R-32 and R-454B are mildly flammable (A2L). No open flame near a leak.`],steps:[{title:`Remote and mode`,who:`anyone`,body:`Cool or Heat, not Fan or Dry. Setpoint actually below/above room temp. Fresh batteries in the remote. Many heads ignore the wall if the remote is in a different mode.`},{title:`Filters and coil`,who:`anyone`,body:`Pop the front panel. Wash the mesh filters. A dusty indoor coil looks like a refrigerant problem.`},{title:`Outdoor unit`,who:`anyone`,body:`Give it 3–5 minutes after a call. Inverters ramp slowly. Confirm the disconnect and breaker. Clear leaves off the coil.`},{title:`Error codes`,who:`helper`,body:`Heads flash a code on the display or LEDs. Photograph it. Codes beat guessing.`},{title:`Communication and charge`,who:`tech`,body:`Check the interconnect cable, flare torque, and weigh-in against the factory 25 ft charge plus add-on. Do not “top off” a mini-split by pressures alone.`}]},{id:`package`,title:`Residential package unit`,summary:`Cooling and often gas or electric heat in one cabinet on a pad or curb.`,safety:[`Same capacitor and gas rules as splits and furnaces.`,`Watch for standing water and rusted drain pans on grade-level units.`],steps:[{title:`Thermostat and disconnect`,who:`anyone`,body:`Confirm mode, setpoint, and the unit disconnect. Package units die from a pulled disconnect more often than people expect.`},{title:`Filters and return`,who:`anyone`,body:`Filters may sit in the unit or in a hallway grille. Check both.`},{title:`Outdoor coil and debris`,who:`anyone`,body:`Cottonwood, grass clippings, and a leaning unit that pinched the drain are the usual pad-unit problems.`},{title:`Heat vs cool`,who:`helper`,body:`If cooling works and heat does not (or the reverse), treat it as two systems in one box. Follow the furnace or heat-pump path for that half.`},{title:`Charge and gas`,who:`tech`,body:`Nameplate charge is usually for the unit as shipped — there is no long lineset. Still weigh and check superheat/subcool.`}]},{id:`rtu`,title:`Commercial rooftop unit`,summary:`Packaged RTU: compressors, condenser fans, indoor blower, often an economizer and 2–4 cooling stages.`,safety:[`Roof work needs fall protection and a safe hatch path.`,`Many RTUs are 208/230 or 460V three-phase. Confirm rotation after any power work.`,`Lockout the disconnect. Economizer dampers pinch fingers.`],steps:[{title:`Building-side checks`,who:`anyone`,body:`What does the thermostat or BAS say? Occupied? Setpoint? Any alarm on the wall stat? Are other units on the same roof running?`},{title:`Power and breaks`,who:`helper`,body:`Roof disconnect, unit breaker, phase loss. A single-phased three-phase compressor will hum and overheat. Do not keep bumping it.`},{title:`Filters, belts, econo`,who:`helper`,body:`Change filters. Check belt tension and cracks. Look at the economizer: stuck open in July cooks the space; stuck shut in swing season wastes cooling.`},{title:`Staging`,who:`helper`,body:`Note which compressors and condenser fans run on a call. One dead circuit can look like “weak AC.”`},{title:`Safeties and charge`,who:`tech`,body:`High/low pressure switches, freezestat, condensate overflow, dirty-filter switch, VFD faults. Recover and weigh by circuit. Do not mix circuits.`}]},{id:`commercial-ahu`,title:`Commercial air handler`,summary:`Large indoor or penthouse AHU feeding VAV boxes or a built-up system.`,safety:[`Fan arrays and VFDs store energy. Follow lockout and wait times on the VFD cover.`,`Entering a unit cabinet is confined-space adjacent work. Prop doors, watch coils and turning vanes.`],steps:[{title:`What the building wants`,who:`anyone`,body:`Read the BAS: occupied mode, SAT setpoint, fan status, damper command, cooling/heating valve command.`},{title:`Air moving?`,who:`helper`,body:`Is the supply fan actually running? Check VFD keypad for a fault. Listen at the unit and at a main diffuser.`},{title:`Filters and coils`,who:`helper`,body:`Loaded bags or a fouled cooling coil drop airflow and trip freezestats. Look at the magnehelic if one is installed.`},{title:`Water side`,who:`helper`,body:`Chilled- or hot-water coil: are the control valve and pump actually stroking? Touch supply and return lines (carefully) for a temperature split.`},{title:`Controls and balance`,who:`tech`,body:`Sequence of operations, static-pressure setpoint, VAV box flow, sensor calibration. Do not chase a “bad chiller” when the AHU valve is closed.`}]},{id:`chiller`,title:`Chiller plant`,summary:`Air-cooled or water-cooled chiller making chilled water for AHUs and fan coils.`,safety:[`This is not homeowner work. High voltage, high pressure vessels, and treated water.`,`Never jumper flow switches, high-pressure safeties, or reliefs.`],steps:[{title:`Is there a chilled-water request`,who:`anyone`,body:`BAS: chiller enable, CHW setpoint, pump status, tower enable. A disabled schedule looks like a dead machine.`},{title:`Pumps and flow`,who:`helper`,body:`Primary pumps must run and prove flow before most chillers will start. Check strainers and isolation valves.`},{title:`Towers (water-cooled)`,who:`helper`,body:`Fans, basin level, makeup water, and condenser-water temperature. A starved tower will high-pressure a chiller in minutes.`},{title:`Air-cooled coils`,who:`helper`,body:`Clear debris, confirm all condenser fans stage, look at the controller alarm log.`},{title:`Refrigerant circuit`,who:`tech`,body:`Approach temps, oil, vanes or VFD unloaders, sensor calibration. Recover only into approved vessels. Call the factory on a screw or centrifugal lockout you have not seen before.`}]},{id:`walk-in`,title:`Walk-in cooler or freezer`,summary:`Box evaporator plus a remote or packaged condensing unit. Door switches and defrost matter as much as charge.`,safety:[`Do not prop a freezer door open for long diagnoses — product and coil ice will pile up.`,`Electric defrost heaters stay live on some boards even when the compressor is off.`],steps:[{title:`Box basics`,who:`anyone`,body:`Door closed and gasket sealing? Lights off when the door is shut? Product blocking the evaporator? Thermostat setpoint sane (cooler ~35°F, freezer ~−10°F)?`},{title:`Evaporator`,who:`helper`,body:`Fans spinning? Coil iced over? A frozen coil needs a full defrost and a drain that actually drips, not more refrigerant.`},{title:`Condensing unit`,who:`helper`,body:`Outside or on the roof: fan running, coil clean, breaker on. Feel whether the liquid line is warm and the suction is cold after a few minutes.`},{title:`Defrost clock`,who:`helper`,body:`Freezers need scheduled defrost. If heaters never run, or run constantly, the box will either ice or never pull down.`},{title:`TXV and charge`,who:`tech`,body:`Superheat at the evaporator, subcool at the condensing unit, and a weigh-in — walk-ins are easy to overcharge. Check the door heater on freezers.`}]},{id:`boiler`,title:`Boiler and hydronic heat`,summary:`Hot water or steam boiler feeding coils, radiators, or a loop.`,safety:[`Gas and carbon monoxide rules from the furnace guide apply.`,`A boiler with no pressure or a dead relief valve is a stop-work condition.`,`Steam systems scald. Treat every valve as hot.`],steps:[{title:`Call for heat`,who:`anyone`,body:`Thermostat or BAS asking for heat? Pumps or zone valves commanded?`},{title:`Water in the system`,who:`helper`,body:`Gauge in range (often 12–20 psi cold on a residential loop). Pressure-reducing valve and expansion tank on the correct side. Cold radiators plus a screaming boiler often means air or no circulation.`},{title:`Boiler ignition`,who:`helper`,body:`Same sequence idea as a furnace: draft fan, igniter, flame. Write down the control fault.`},{title:`Loop`,who:`helper`,body:`Feel supply vs return after 10 minutes. If they are equal, flow is dead (pump, zone valve, air lock).`},{title:`Combustion and reliefs`,who:`tech`,body:`Combustion analysis, low-water cutoff test, relief valve, flame rollout, and a real look at the heat exchanger. Do not plug a leaking relief.`}]}];function a(e){return i.find(t=>t.id===e)}export{a,n as i,i as n,r as o,t as r,e as t};